import{_ as t,o as e,a as d,b as o}from"./app.UgfkfLuP.js";const n=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"},{"text":"Reg与UB数据搬运","link":"/api/SIMD-API/c_api/data_move_guide/reg_ub_data_move"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/reg_ub_data_move.md","filePath":"api/SIMD-API/c_api/data_move_guide/reg_ub_data_move.md","outlineHeaders":[{"level":2,"title":"接口选择","slug":"接口选择","link":"#接口选择"},{"level":3,"title":"UB搬入Reg","slug":"UB搬入Reg","link":"#UB搬入Reg"},{"level":3,"title":"Reg搬出UB","slug":"Reg搬出UB","link":"#Reg搬出UB"},{"level":2,"title":"地址维护方式","slug":"地址维护方式","link":"#地址维护方式"},{"level":2,"title":"非对齐搬运","slug":"非对齐搬运","link":"#非对齐搬运"},{"level":3,"title":"非对齐搬入","slug":"非对齐搬入","link":"#非对齐搬入"},{"level":3,"title":"非对齐搬出","slug":"非对齐搬出","link":"#非对齐搬出"},{"level":2,"title":"使用约束","slug":"使用约束","link":"#使用约束"}],"lastUpdated":1790563388000}'),l={name:"api/SIMD-API/c_api/data_move_guide/reg_ub_data_move.md"};function _(r,a,s,c,p,i){return e(),d("div",null,[...a[0]||(a[0]=[o('<div><article class="markdown-body"><h1>Reg与UB数据搬运</h1><div data-filter="950"><p>Reg数据搬入接口用于将Unified Buffer（UB）中的数据搬入矢量数据寄存器、掩码寄存器或非对齐寄存器，Reg数据搬出接口用于将寄存器中的数据写回UB。两类接口均仅在AIV上生效，且需在Vector Function（<code>__simd_vf__</code>标记的函数）内调用。</p><p>NPU架构版本3510的矢量数据寄存器长度（VL）为256字节，掩码寄存器长度为32字节。单个矢量数据寄存器可容纳的元素个数由数据位宽决定，例如b16为128个元素，b32为64个元素。接口的完整模式、地址对齐要求、原理图和示例分别参见<a href="../reg_compute/load/reg_load_overview.html">Reg数据搬入概述</a>和<a href="../reg_compute/store/reg_store_overview.html">Reg数据搬出概述</a>。本节按使用场景提炼接口选择方法。</p><h2 id="接口选择">接口选择<a class="header-anchor" href="#接口选择">​</a></h2><h3 id="UB搬入Reg">UB搬入Reg<a class="header-anchor" href="#UB搬入Reg">​</a></h3><table><thead><tr><th>接口模式</th><th>代表接口</th><th>选择说明</th></tr></thead><tbody><tr><td>连续/立即数/地址寄存器偏移搬入</td><td><a href="../reg_compute/load/asc_loadalign.html">asc_loadalign</a></td><td>搬入一个VL，可由调用方计算地址，也可使用立即数偏移或地址寄存器偏移。</td></tr><tr><td>立即数偏移/非连续对齐Post Update搬入</td><td><a href="../reg_compute/load/asc_loadalign_postupdate.html">asc_loadalign_postupdate</a></td><td>搬入后自动更新源地址，适合连续迭代；不提供地址寄存器偏移原型。</td></tr><tr><td>非连续对齐搬入</td><td><a href="../reg_compute/load/asc_loadalign.html">asc_loadalign</a>、<a href="../reg_compute/load/asc_loadalign_datablock_strided.html">asc_loadalign_datablock_strided</a></td><td>按配置的DataBlock步长非连续搬入8个DataBlock。</td></tr><tr><td>广播搬入</td><td><a href="../reg_compute/load/asc_loadalign_brc_datablock.html">asc_loadalign_brc_datablock</a>、<a href="../reg_compute/load/asc_loadalign_brc_elem.html">asc_loadalign_brc_elem</a>、<a href="../reg_compute/load/asc_loadalign_brc_elem2datablock.html">asc_loadalign_brc_elem2datablock</a></td><td>分别支持DataBlock广播、单元素广播以及将8个元素分别广播到8个DataBlock。</td></tr><tr><td>解交织/采样/解包搬入</td><td><a href="../reg_compute/load/asc_loadalign_deintlv.html">asc_loadalign_deintlv</a>、<a href="../reg_compute/load/asc_loadalign_downsample.html">asc_loadalign_downsample</a>、<a href="../reg_compute/load/asc_loadalign_upsample.html">asc_loadalign_upsample</a>、<a href="../reg_compute/load/asc_loadalign_unpack.html">asc_loadalign_unpack</a>、<a href="../reg_compute/load/asc_loadalign_unpack4.html">asc_loadalign_unpack4</a></td><td>支持解交织、2倍下采样、2倍上采样、二分之一解包和四分之一解包。</td></tr><tr><td>连续非对齐搬入（易用形式）</td><td><a href="../reg_compute/load/asc_load.html">asc_load</a></td><td>源地址按<code>dtype</code>对齐即可，接口负责完成一个VL的连续搬入。</td></tr><tr><td>连续非对齐搬入（高性能形式）</td><td><a href="../reg_compute/load/asc_loadunalign_pre.html">asc_loadunalign_pre</a>、<a href="../reg_compute/load/asc_loadunalign.html">asc_loadunalign</a>、<a href="../reg_compute/load/asc_loadunalign_postupdate.html">asc_loadunalign_postupdate</a></td><td>使用<code>vector_load_unalign</code>保存跨32字节边界的数据，适合需要显式复用非对齐状态的场景。</td></tr><tr><td>掩码寄存器连续对齐搬入</td><td><a href="../reg_compute/load/asc_loadalign.html">asc_loadalign</a>、<a href="../reg_compute/load/asc_loadalign_postupdate.html">asc_loadalign_postupdate</a>、<a href="../reg_compute/load/asc_loadalign_mask.html">asc_loadalign_mask</a></td><td>支持直接搬入、Post Update搬入或通过返回值搬入。</td></tr><tr><td>掩码寄存器采样搬入</td><td><a href="../reg_compute/load/asc_loadalign_downsample.html">asc_loadalign_downsample</a>、<a href="../reg_compute/load/asc_loadalign_downsample_postupdate.html">asc_loadalign_downsample_postupdate</a>、<a href="../reg_compute/load/asc_loadalign_mask_downsample.html">asc_loadalign_mask_downsample</a>、<a href="../reg_compute/load/asc_loadalign_upsample.html">asc_loadalign_upsample</a>、<a href="../reg_compute/load/asc_loadalign_upsample_postupdate.html">asc_loadalign_upsample_postupdate</a>、<a href="../reg_compute/load/asc_loadalign_mask_upsample.html">asc_loadalign_mask_upsample</a></td><td>支持2倍下采样和2倍上采样，可选择Post Update或返回值形式。</td></tr></tbody></table><h3 id="Reg搬出UB">Reg搬出UB<a class="header-anchor" href="#Reg搬出UB">​</a></h3><table><thead><tr><th>接口模式</th><th>代表接口</th><th>选择说明</th></tr></thead><tbody><tr><td>连续/立即数/地址寄存器偏移/非连续对齐搬出</td><td><a href="../reg_compute/store/asc_storealign.html">asc_storealign</a></td><td>按<code>mask</code>连续写入一个VL，或按DataBlock步长写入。</td></tr><tr><td>立即数偏移/非连续对齐Post Update搬出</td><td><a href="../reg_compute/store/asc_storealign_postupdate.html">asc_storealign_postupdate</a></td><td>搬出后自动更新目的地址，适合连续迭代；不提供地址寄存器偏移原型。</td></tr><tr><td>搬出首元素</td><td><a href="../reg_compute/store/asc_storealign_1st.html">asc_storealign_1st</a>、<a href="../reg_compute/store/asc_storealign_1st_postupdate.html">asc_storealign_1st_postupdate</a></td><td>仅将矢量数据寄存器的首个元素写入UB，可选择是否自动更新目的地址。</td></tr><tr><td>交织搬出</td><td><a href="../reg_compute/store/asc_storealign_intlv.html">asc_storealign_intlv</a></td><td>将两个矢量数据寄存器按元素交织后写入UB。</td></tr><tr><td>压缩搬出</td><td><a href="../reg_compute/store/asc_storealign_pack.html">asc_storealign_pack</a>、<a href="../reg_compute/store/asc_storealign_pack_quarter.html">asc_storealign_pack_quarter</a></td><td>分别将有效元素的低半部分bit或32位元素的低8bit压缩后写入UB。</td></tr><tr><td>连续搬出（易用形式）</td><td><a href="../reg_compute/store/asc_store.html">asc_store</a></td><td>可搬出整个矢量数据寄存器或前<code>count</code>个元素；具体对齐场景按接口文档选择<code>asc_storealign</code>或非对齐接口。</td></tr><tr><td>非对齐搬出</td><td><a href="../reg_compute/store/asc_storeunalign.html">asc_storeunalign</a>、<a href="../reg_compute/store/asc_storeunalign_postupdate.html">asc_storeunalign_postupdate</a></td><td>使用<code>vector_store_unalign</code>暂存不能立即写出的尾块，并在连续搬出结束后调用配套后处理接口。</td></tr><tr><td>掩码寄存器连续对齐搬出</td><td><a href="../reg_compute/store/asc_storealign.html">asc_storealign</a>、<a href="../reg_compute/store/asc_storealign_postupdate.html">asc_storealign_postupdate</a></td><td>支持直接搬出和Post Update搬出。</td></tr><tr><td>掩码寄存器压缩搬出</td><td><a href="../reg_compute/store/asc_storealign_pack.html">asc_storealign_pack</a>、<a href="../reg_compute/store/asc_storealign_pack_postupdate.html">asc_storealign_pack_postupdate</a></td><td>每间隔1bit丢弃1bit，将保留bit压缩后写入UB。</td></tr><tr><td>掩码寄存器非对齐搬出</td><td><a href="../reg_compute/store/asc_storeunalign_postupdate.html">asc_storeunalign_postupdate</a></td><td>提取掩码寄存器中的有效bit并打包写入UB，结束后调用配套后处理接口。</td></tr></tbody></table><h2 id="地址维护方式">地址维护方式<a class="header-anchor" href="#地址维护方式">​</a></h2><p>对齐连续搬入和搬出可按具体接口选择以下地址维护方式，选择原则与两篇现有概述中的对比表一致；并非每个接口都同时支持所有方式：</p><ul><li>调用方通过指针运算计算每次访问的地址，适合偏移规则简单且需要显式控制地址的场景。</li><li>将相对基地址的立即数偏移传入接口，适合需要保留基地址且偏移可由普通整数表示的场景。</li><li>通过<a href="../reg_compute/reg_addr_reg/asc_update_addr_reg.html">asc_update_addr_reg</a>生成<code>addr_reg</code>，适合Hardware Loop内偏移随迭代变化的场景。</li><li>使用Post Update接口，在完成搬入或搬出后自动更新地址。</li></ul><p><code>asc_loadalign_postupdate</code>和<code>asc_storealign_postupdate</code>仅支持通过立即数参数指定地址更新量，以及各自的非连续对齐原型，不提供<code>addr_reg</code>参数。地址寄存器偏移应使用<code>asc_loadalign</code>或<code>asc_storealign</code>等非Post Update接口；非对齐接口的支持情况以具体原型为准。</p><p>偏移单位随接口和寄存器类型变化。矢量数据偏移通常以元素为单位，掩码地址偏移可能以字节为单位，非连续模式还可能以DataBlock为单位，具体以接口参数说明为准。</p><h2 id="非对齐搬运">非对齐搬运<a class="header-anchor" href="#非对齐搬运">​</a></h2><p>非对齐搬运用于有效起始地址满足<code>dtype</code>对齐、但不满足32字节对齐的连续数据访问场景。详细原理和配合关系参见<a href="../reg_compute/load/reg_load_overview.html#%E9%9D%9E%E5%AF%B9%E9%BD%90%E6%90%AC%E8%BF%90%E7%89%B9%E6%80%A7">Reg数据搬入概述中的非对齐搬运特性</a>。</p><h3 id="非对齐搬入">非对齐搬入<a class="header-anchor" href="#非对齐搬入">​</a></h3><p><code>asc_load</code>是连续非对齐搬入的易用接口。需要显式复用非对齐状态时，先调用<code>asc_loadunalign_pre</code>，再调用<code>asc_loadunalign</code>或<code>asc_loadunalign_postupdate</code>。普通<code>asc_loadunalign</code>每次搬入前均需重新预处理；连续调用立即数偏移形式的<code>asc_loadunalign_postupdate</code>时，可复用接口更新后的非对齐寄存器，源地址被另行修改后必须重新预处理。</p><p>非对齐搬入会访问有效起始地址向低地址方向按32字节对齐后的范围，因此该范围也必须位于已分配的UB空间内。</p><h3 id="非对齐搬出">非对齐搬出<a class="header-anchor" href="#非对齐搬出">​</a></h3><p>非对齐主搬出接口将完整块写入UB，并把末尾不足对齐块的数据暂存在<code>vector_store_unalign</code>中。连续调用时必须复用同一个非对齐寄存器，结束后按下表调用配套后处理接口写出最后一个尾块。</p><table><thead><tr><th>主搬出方式</th><th>配套后处理接口</th><th>地址维护方式</th></tr></thead><tbody><tr><td><a href="../reg_compute/store/asc_storeunalign.html">asc_storeunalign</a></td><td><a href="../reg_compute/store/asc_storeunalign_post.html">asc_storeunalign_post</a></td><td>调用方更新目的地址。</td></tr><tr><td><a href="../reg_compute/store/asc_storeunalign_postupdate.html">asc_storeunalign_postupdate</a>立即数偏移模式</td><td><a href="../reg_compute/store/asc_storeunalign_post_postupdate.html">asc_storeunalign_post_postupdate</a></td><td>主接口自动更新目的地址。</td></tr><tr><td><a href="../reg_compute/store/asc_storeunalign_postupdate.html">asc_storeunalign_postupdate</a>地址寄存器偏移模式</td><td><a href="../reg_compute/store/asc_storeunalign_post.html">asc_storeunalign_post</a></td><td>主接口自动更新地址寄存器，主搬出和后处理接口复用该寄存器。</td></tr></tbody></table><h2 id="使用约束">使用约束<a class="header-anchor" href="#使用约束">​</a></h2><ul><li>各模式的实际访问地址必须满足对应接口的对齐要求，实际访问范围必须位于可用UB空间内且不能越界。</li><li>多条Reg指令访问重叠UB区域并存在读写冲突时，使用<a href="../reg_compute/reg_sync/asc_mem_bar.html">asc_mem_bar</a>保证执行顺序。</li><li>b64数据类型仅由部分接口支持，且地址寄存器偏移和掩码构造方式不同，具体参见<a href="../reg_compute/load/reg_load_overview.html#b64%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B%E7%9A%84%E6%90%AC%E8%BF%90">Reg数据搬入概述中的b64数据类型搬运</a>。</li><li>寄存器类型及声明方式参见<a href="../defs/type/reg_data_types.html">寄存器类型</a>。</li></ul></div></article></div>',1)])])}const h=t(l,[["render",_]]);export{n as __pageData,h as default};
